import { Align } from "@kvisaz/phaser-sugar";
import { FontFamily, Scenes } from "../../common/game-core";
import { goScene } from "../../common/scenes";
import { getSearchParam, setSearchParam } from "../../common";
import { testScenes } from "./testScenes";
import { addTestButtons } from "./utils";
import { ViewElementBuilder } from "../../assets";

/**
 * @deprecated Используй storybook (`klondikeGameView.story.ts`) или GameScene с флагами вместо встроенных тест-сцен.
 */
export class TestScene extends Phaser.Scene {
  constructor() {
    super(Scenes.TestScene);
  }

  create() {
    const scene = this;
    const align = new Align();
    const builder = new ViewElementBuilder(scene);
    builder.backgroundGameScene();

    /** title **/
    const titleView = new Phaser.GameObjects.Text(scene, 0, 0, "Test scenes", {
      fontFamily: FontFamily.MainBold,
      color: "#c7d7e1",
      fontSize: "32px",
    });
    this.add.existing(titleView);
    align.anchorSceneScreen(scene).center(titleView).topIn(titleView, 30);

    /**
     * test scenes runner
     ***/
    const runTestScene = (sceneKey: keyof typeof testScenes) => {
      goScene({
        fromScene: this,
        key: sceneKey,
        toScene: testScenes[sceneKey](sceneKey),
      });
    };

    /** auto-run tests for url param for hot reload **/
    const sceneKey = getSearchParam("test");
    if (sceneKey && sceneKey in testScenes) {
      runTestScene(sceneKey as keyof typeof testScenes);
    }

    type TestSceneKey = keyof typeof testScenes;
    const sceneKeys = Object.keys(testScenes) as TestSceneKey[];

    /** Layout **/
    addTestButtons({
      scene: this,
      title: "Test scenes",
      buttonsData: sceneKeys.map((sceneKey) => ({
        text: sceneKey,
        onClick: () => {
          runTestScene(sceneKey);
          setSearchParam("test", sceneKey);
        },
      })),
    });
  }
}
