import { StateConnector } from "../../common";
import { CoreBehavior } from "../../common/game-core";
import { GameEvents, gameStateStore, GoodyType, IPlayerGoodyState } from "../../logic";
import { ViewElementBuilder } from "../../assets";

/** Consumables — это ограниченный ресурс (дейлики, награды, реклама, инаппы),
 *  поэтому значения живут в глобальном memoryStorage и не сбрасываются между сессиями.
 */
export class KlondikeConsumablesBehavior extends CoreBehavior {
  protected gameEvents: GameEvents | undefined;
  private consumables?: StateConnector<IPlayerGoodyState>;
  private goodyOverlay?: Phaser.GameObjects.GameObject;

  create(scene: Phaser.Scene) {
    this.addUnSub(() => this.goodyOverlay?.destroy());

    const gameEvents = new GameEvents(scene);
    this.gameEvents = gameEvents;
    this.addUnSub(() => {
      gameEvents.unSubscribeAll();
      this.gameEvents = undefined;
    });

    this.consumables = gameStateStore.getStateConnector("playerGoodyState");
    this.addUnSub(() => this.consumables?.unSubScribeAll());

    /** consumableUndoButton reaction  **/
    gameEvents.on("onUndoButtonClick", () => {
      const state = this.consumables?.getState();
      const isUndoApproved = (state?.undoAmount ?? 0) > 0;
      console.log("CONSUMABLES - onUndoButtonClick, isUndoApproved", isUndoApproved);

      if (!isUndoApproved) return;

      /** order to undo **/
      gameEvents.emit("doKlondikeUnDo");

      this.goodyOverlay = this.showGoodyOverlay({ scene, goody: GoodyType.UNDO });

      gameEvents.once("klondikeUndoCardMoveFinished", () => {
        this.goodyOverlay?.destroy();
        this.consumables?.setState((prev) => ({
          ...prev,
          undoAmount: Math.max(0, prev.undoAmount - 1),
        }));
      });
    });

    gameEvents.on("onHintButtonClick", () => {
      const state = this.consumables?.getState();
      const isHintApproved = (state?.hintAmount ?? 0) > 0;

      if (!isHintApproved) return;
      gameEvents.emit("doKlondikeHint");
      this.consumables?.setState((prev) => ({
        ...prev,
        hintAmount: Math.max(0, prev.hintAmount - 1),
      }));
    });

    gameEvents.on("onVisionButtonClick", () => {
      const state = this.consumables?.getState();
      const isVisionApproved = (state?.visionAmount ?? 0) > 0;

      const durationMs = 3000;
      this.goodyOverlay = this.showGoodyOverlay({ scene, goody: GoodyType.VISION, durationMs });
      if (!isVisionApproved) return;
      gameEvents.emit("doKlondikeVision", { durationMs });
      this.consumables?.setState((prev) => ({
        ...prev,
        visionAmount: Math.max(0, prev.visionAmount - 1),
      }));
    });

    gameEvents.on("onMagicButtonClick", () => {
      const state = this.consumables?.getState();
      const isMagicApproved = (state?.magicAmount ?? 0) > 0;

      if (!isMagicApproved) return;
      const durationMs = 600;
      this.goodyOverlay = this.showGoodyOverlay({ scene, goody: GoodyType.MAGIC, durationMs });
      gameEvents.emit("doKlondikeMagic", { durationMs });
      this.consumables?.setState((prev) => ({
        ...prev,
        magicAmount: Math.max(0, prev.magicAmount - 1),
      }));
    });
  }

  private showGoodyOverlay(args: { scene: Phaser.Scene; goody: GoodyType; durationMs?: number }) {
    return new ViewElementBuilder(args.scene).effectGoody({
      goody: args.goody,
      durationMs: args.durationMs,
    });
  }
}
