import { CardSuit, CardValue, ClassicCardData, KlondikeStackType, SafeSceneEventsAdapter } from "../common";
import { onSceneShutdown } from "../common/scenes";
import { SoundKey } from "./models";

/** Эвенты конкретной игры
 * в формате key->dataType э**/
export interface IGameEvents{
  /** ----
   * универсальные эвенты всех игр
   * ---------- **/

  /** управление родительской сценой **/
  parentScenePause: void;
  parentSceneResume: void;

  /** ----
   * конкретные эвенты данной игры
   * ---------- **/

  /** текущее время игрового сеанса
   * - издается таймером
   * - читается в UI и возможно логике
   * **/
  gameSessionTimerCurrentTimeMs: number;


  onNewGameButtonClick: void;
  onReplayGameButtonClick: void;
  onUndoButtonClick: void;
  onHintButtonClick: void;
  onVisionButtonClick: void;
  onMagicButtonClick: void;
  settingsDialogRequested: void;

  /** timer  */
  commandGameSessionTimer: 'start' | 'stop' | 'pause' | 'resume' | 'clear';

  /** gameView  */
  gameViewStartKlondike: { cards: ClassicCardData[] };

  /** events for klondike */
  doKlondikeUnDo: void;
  doKlondikeHint: void; // todo { durationMs: number }
  doKlondikeVision: { durationMs: number };
  doKlondikeMagic: { durationMs: number };

  /** events from klondike */
  klondikeOnDealFinish: void;
  klondikeShowHint: void;

  klondikeUndoCardMove: void;
  klondikeUndoCardMoveFinished: void;
  klondikeHintShown: {
    suit: CardSuit;
    value: CardValue;
    fromStack: { type: KlondikeStackType; id: string };
  };
  klondikeCardMove: {
    suit: CardSuit;
    value: CardValue;
    fromStack: { type: KlondikeStackType; id: string };
    toStack: { type: KlondikeStackType; id: string };
  };
  klondikeCardSound: void;
  klondikeCardAutoMoveFail: {
    suit: CardSuit;
    value: CardValue;
    fromStack: { type: KlondikeStackType; id: string };
  };
}

/**
 * Подключи внутри сцены или объекта
 * с закрытием сцены или объекта - автоматически отпишется от своих подписок в этом инстансте
 * по сути подключается к общей scene.events
 * поэтому живые инстансы GameEvents могут сосущесвовать вместе
 * и слушать события отправляем друг от друга
 *
 * Не забудь вручную добавлять в отписки в объекты не являющиеся scene / gameobject
 ***/
export class GameEvents extends SafeSceneEventsAdapter<IGameEvents> {
  constructor(host: Phaser.Scene | Phaser.GameObjects.GameObject) {
    super(host instanceof Phaser.Scene ? host : host.scene);

    const onDestroy = () => this.unSubscribeAll();
    if (host instanceof Phaser.Scene) {
      onSceneShutdown(host, onDestroy);
    } else {
      host.on(Phaser.GameObjects.Events.DESTROY, onDestroy);
    }
  }
}
