import { Align, AlignObject } from "@kvisaz/phaser-sugar";
import { FullscreenOverlay } from "../../../../common/game-core";
import { safeArray } from "../../../../common";

interface IEffectOverlayProps {
  scene: Phaser.Scene;
  icon: Phaser.GameObjects.Image & AlignObject;
  durationMs?: number;
  depth?: number;
  overlayAlpha: number;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
}

export class EffectOverlay extends Phaser.GameObjects.Container {
  private timer?: Phaser.Time.TimerEvent;
  private readonly overlay: Phaser.GameObjects.Rectangle;
  private readonly countdown: Phaser.GameObjects.Text | undefined;
  private icon: Phaser.GameObjects.Image & AlignObject;

  constructor(protected props: IEffectOverlayProps) {
    super(props.scene, 0, 0);
    const { scene, icon, durationMs, depth = 1000, overlayAlpha, textBuilder } = props;
    this.setDepth(depth);

    this.icon = icon;
    this.overlay = new FullscreenOverlay({
      scene,
      alpha: overlayAlpha,
      interactive: true,
    });

    this.icon.postFX.addShine(1.5);

    this.countdown = durationMs != null ? textBuilder("") : undefined;
    const children: Phaser.GameObjects.GameObject[] = safeArray([
      this.overlay,
      icon,
      this.countdown,
    ]);

    const align = new Align();
    align.anchorSceneScreen(scene).center(icon).topIn(icon, 32);
    if (this.countdown && durationMs != null) {
      this.startCountdown(durationMs);
    }

    this.add(children);
    scene.add.existing(this);
    align.anchorSceneScreen(scene).center(this);
  }

  private layoutCounter(){
    if(!this.countdown) return;
    new Align(this.icon).centerX(this.countdown).bottomTo(this.countdown, 16);
  }

  destroy() {
    super.destroy();
    this.timer?.remove(false);
    this.overlay.destroy();
  }

  private startCountdown(durationMs: number) {
    let remaining = Math.ceil(durationMs / 1000);
    this.countdown?.setText("" + remaining);
    this.layoutCounter();
    this.timer = this.scene.time.addEvent({
      delay: 1000,
      loop: true,
      callback: () => {
        remaining -= 1;
        this.countdown?.setText("" + Math.max(0, remaining));
        this.layoutCounter();
        if (remaining <= 0) {
          this.destroy();
        }
      },
    });
  }
}
