import { Align } from "@kvisaz/phaser-sugar";
import { ContainerButton } from "../../../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
  name?: string;
  onClick: () => void;
  onHover?: () => void;
  buttonImageBuilder: () => Phaser.GameObjects.Image;
  initAmount?: number;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
  textBgBuilder: (w: number, h: number) => Phaser.GameObjects.NineSlice;
}

/**
 * Универсальная кнопка с указателем какого-то числа amount
 * дизайн по умолчанию - число справа
 *
 * @bug есть минорный баг - hitArea рассчитывается не на всю ширину с текстом
 * но при текущем расположении кнопок слева на экране это выглядит фичей
 **/
export class ConsumableButton extends ContainerButton {
  protected amount: number;
  protected content: {
    icon: Phaser.GameObjects.Image;
    textBg: Phaser.GameObjects.NineSlice;
    text: Phaser.GameObjects.Text;
  };

  constructor(props: IProps) {
    const content = createContentGameObjects(props);
    super({
      gameObjects: [content.textBg, content.text, content.icon],
      onClick: props.onClick,
      onOver: props.onHover,
      options: {
        once: false,
        onDisabled: () => {
          content.icon.setTint(0xa0a0a0);
          this.updateEnableText();
        },
        onEnabled: () => {
          content.icon.clearTint();
          this.updateEnableText();
        },
        disableAfterClick: {
          ms: 0,
        },
      },
    });
    this.content = content;
    this.name = props.name ?? "consumableButton";
    this.amount = Math.max(0, props.initAmount ?? 0);
    this.layout();
  }

  layout() {
    const align = new Align();
    const { text, textBg, icon } = this.content;

    const textBgWidth = 60 + text.width;
    textBg.width = textBgWidth;
    align.anchor(icon).centerY(textBg).rightTo(textBg, -32);
    align.anchor(icon).centerY(text).rightTo(text, 8);

    const { width, height } = this.getBounds();
    this.setSize(width, height);
    this.input?.hitArea?.setSize(width, height);
  }

  setAmount(amount: number) {
    if (this.scene == null) return;
    this.amount = Math.max(0, amount);
    this.content.text.setText(`${this.amount}`);
    this.layout();
  }

  protected updateEnableText() {
    const alpha = this.isEnabled ? 1 : 0.35;
    this.content.textBg.setAlpha(alpha);
    this.content.text.setAlpha(alpha);
  }

  protected addOverEffect() {
    if (this.isOverEffect) return;
    this.isOverEffect = true;
    this.content.icon.postFX?.addGlow?.();
    this.content.textBg.postFX?.addGlow?.();
  }

  protected clearOverEffect() {
    if (!this.isOverEffect) return;
    this.isOverEffect = false;
    this.content.icon.postFX?.clear?.();
    this.content.textBg.postFX?.clear?.();
  }
}

function createContentGameObjects(props: IProps): {
  icon: Phaser.GameObjects.Image;
  textBg: Phaser.GameObjects.NineSlice;
  text: Phaser.GameObjects.Text;
} {
  const textBg = props.textBgBuilder(90, 68);
  const text = props.textBuilder(`${props.initAmount ?? 0}`);
  const icon = props.buttonImageBuilder();

  return {
    icon,
    textBg,
    text,
  };
}
