import { Align } from "@kvisaz/phaser-sugar";
import { FontFamily } from "../../../../../common/game-core";
import { Locale } from "../../../../../logic";
import { CardSuit, CardValue, fitToSize, getCardLetter, isNumberCard } from "../../../../../common";
import { layoutNumberCard } from "./layoutNumberCard";
import { getCurrentLocale } from "../../../../locale";
import { ImageAsset } from "../../index";

type AssetPack = {
  mainIcon: ImageAsset;
  cornerIcon: ImageAsset;
  jack: ImageAsset;
  queen: ImageAsset;
  king: ImageAsset;
};

export interface ICardBuilderAssets {
  faceFrameAsset: ImageAsset;
  faceBgAsset: ImageAsset;
  cardPlaceBase: ImageAsset;
  cardPlaceCommon: ImageAsset;
  backCoverAsset: ImageAsset;
  suitMap: Record<CardSuit, AssetPack>;
}

interface IProps {
  scene: Phaser.Scene;
  assets: ICardBuilderAssets;
  colorRed?: string;
  colorBlack?: string;
}

/**
 * билдер для обычных игровых кард на 52 карты
 * методы не должны меняться ни для одного пасьянса!
 * меняется только атласы - а в них нейминг один и тот жe
 * **/
export class CardAssetBuilder {
  private readonly scene: Phaser.Scene;
  private readonly locale: Locale;
  private readonly colorRed: string;
  private readonly colorBlack: string;

  constructor(private props: IProps) {
    this.scene = props.scene;
    this.locale = getCurrentLocale();
    this.colorRed = props.colorRed ?? "#BC1E24";
    this.colorBlack = props.colorBlack ?? "#000000";
  }

  private getSuitColor(suit: CardSuit): string {
    if (suit === CardSuit.diamond) return this.colorRed;
    if (suit === CardSuit.heart) return this.colorRed;
    return "#000000";
  }

  private getFigureAsset(suit: CardSuit, value: CardValue): ImageAsset | undefined {
    const assetPack = this.props.assets.suitMap[suit];
    if (value === "jack") return assetPack.jack;
    if (value === "queen") return assetPack.queen;
    if (value === "king") return assetPack.king;
    return undefined;
  }

  private figure(suit: CardSuit, value: CardValue): Phaser.GameObjects.Image | undefined {
    const imageAsset = this.getFigureAsset(suit, value);
    if (!imageAsset) return;
    return this.image(imageAsset);
  }

  private faceFrame() {
    return this.image(this.props.assets.faceFrameAsset);
  }

  private faceBg() {
    return this.image(this.props.assets.faceBgAsset);
  }

  private backCover() {
    return this.image(this.props.assets.backCoverAsset);
  }

  back() {
    const cover = this.backCover();
    const bg = this.faceBg();
    const frame = this.faceFrame();
    new Align(frame).center(bg).center(cover);

    return new Phaser.GameObjects.Container(this.scene, 0, 0, [bg, cover, frame]);
  }

  cardPlace(isBase = false) {
    const imageAsset = isBase ? this.props.assets.cardPlaceBase : this.props.assets.cardPlaceCommon;
    return this.image(imageAsset);
  }

  private suit(suit: CardSuit) {
    const assetPack = this.props.assets.suitMap[suit];
    const imageAsset = assetPack.mainIcon;
    return this.image(imageAsset);
  }

  private value(suit: CardSuit, value: CardValue) {
    const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
      fontSize: "62px",
      fontFamily: FontFamily.MainSemiBold,
      color: this.getSuitColor(suit),
      letterSpacing: -7,
    };

    const label = getCardLetter(value, this.locale);

    return new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
  }

  cardFace(suit: CardSuit, value: CardValue) {
    const align = new Align();
    const bg = this.faceBg();
    const frame = this.faceFrame();

    const contentContainer = new Phaser.GameObjects.Container(this.scene);
    align.anchor(bg).center(frame);

    const bgBounds = bg.getBounds();

    /** figure layout **/
    const figure = this.figure(suit, value);
    if (figure) {
      fitToSize({
        gameObject: figure,
        width: bgBounds.width,
        height: bgBounds.height,
      });
      contentContainer.add(figure);
      align.anchor(frame).center(contentContainer);
    }

    /** number layout **/
    if (isNumberCard(value) || value === "ace") {
      const isSingle = false;
      if (isSingle) {
        const singleSuit = this.suit(suit).setScale(2.4).setAlpha(0.9);
        contentContainer.add(singleSuit);
      } else {
        const contentImages = layoutNumberCard({ value, align, builder: () => this.suit(suit) });
        contentContainer.add(contentImages);
      }
    }
    const contentOffsetY = figure == null ? 16 : 0;
    align.anchor(frame).center(contentContainer, 0, contentOffsetY);

    const cornerPadding = 12;
    /** corner letter **/
    const valueLetter = this.value(suit, value);
    const letterPadding = Math.floor(cornerPadding * 0.6);
    align.anchor(frame).leftIn(valueLetter, cornerPadding).topIn(valueLetter, letterPadding);

    /** corner value **/
    const suitImage = this.suit(suit).setScale(0.8);
    align.anchor(frame).rightIn(suitImage, -cornerPadding).topIn(suitImage, cornerPadding);

    return new Phaser.GameObjects.Container(this.scene, 0, 0, [bg, contentContainer, valueLetter, suitImage, frame]);
  }

  private image({ url, frameName }: ImageAsset) {
    return this.scene.add.existing(new Phaser.GameObjects.Image(this.scene, 0, 0, url, frameName));
  }
}
